import sys
def _fail(t, e, tb, _d=sys.excepthook):
    if issubclass(t, AssertionError):
        print('check failed:', e); sys.exit(1)
    _d(t, e, tb)
sys.excepthook = _fail
import ast, glob, hashlib, collections
by = collections.defaultdict(list)
for f in sorted(glob.glob('_tools/*.py')):
    if '/test_' in f or f.endswith('conftest.py'): continue
    for n in ast.parse(open(f, encoding='utf-8').read()).body:
        if isinstance(n, ast.FunctionDef):
            b = n.body[1:] if (n.body and isinstance(n.body[0], ast.Expr) and isinstance(getattr(n.body[0], 'value', None), ast.Constant)) else n.body
            if n.end_lineno - n.lineno + 1 >= 4:
                by[hashlib.sha1(ast.dump(ast.Module(body=b, type_ignores=[])).encode()).hexdigest()].append((f.split('/')[-1], n.name))
groups = [v for v in by.values() if len({x[0] for x in v}) > 1 and {x[0] for x in v} & {'bl_dispatch.py', 'bl_procs.py', 'bl_intake.py', 'ql_base.py', 'mon_sprint.py', 'mon_log.py', 'kg_trailers.py', 'mon_sessions.py'}]
print('identical function bodies across modules:', groups)
sys.exit(1 if groups else 0)
